fn extract_rear_chars(s: &Vec<Vec<char>>) -> Vec<char> {
    // For each inner Vec<char>, take its last element.
    // We can safely unwrap because the problem guarantees each inner sequence is non-empty.
    s.iter()
     .map(|inner| *inner.last().unwrap())
     .collect()
}

